import{_ as a,b as t,a as r,aS as l}from"./chunks/framework.M2Whok06.js";const u=JSON.parse('{"title":"10-国内各种税","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/10-国内各种税.md","filePath":"note/knowledge/10-国内各种税.md","lastUpdated":1747752447000}'),o={name:"note/knowledge/10-国内各种税.md"},e=l('<h1 id="_10-国内各种税" tabindex="-1">10-国内各种税 <a class="header-anchor" href="#_10-国内各种税" aria-label="Permalink to &quot;10-国内各种税&quot;">​</a></h1><h2 id="增值税、企业所得税是什么-如何计算" tabindex="-1">增值税、企业所得税是什么，如何计算？ <a class="header-anchor" href="#增值税、企业所得税是什么-如何计算" aria-label="Permalink to &quot;增值税、企业所得税是什么，如何计算？&quot;">​</a></h2><p>目前我国共有十八大税种，包含了增值税、附加税、企业所得税、个人所得税、印花税 、房产税等等，其中增值税、附加税、企业所得税、个人所得税是企业主在日常经营活动中最常见的税种，少不了要和这几个税种打交道的，初次了解，最重点的也是这几个税种。</p><h3 id="一、增值税" tabindex="-1">一、增值税 <a class="header-anchor" href="#一、增值税" aria-label="Permalink to &quot;一、增值税&quot;">​</a></h3><blockquote><p>“增值税是以商品（含 应税劳务 ）在流转过程中产生的增值额作为计税依据而征收的一种 流转税 。从计税原理上说，增值税是对商品生产、流通、劳务服务中多个环节的新增价值或商品的附加值征收的一种流转税。实行 价外税 ，也就是由消费者负担，有增值才征税没增值不征税”</p></blockquote><p>简单来说，就是某样东西，在你手里涨价了后卖出去，那么涨价（增值）这部分就需要交税。</p><p>所以，增值税是一种流转税，伴随着商品在流转的过程中，不断升值，而对升值部分征收的税。</p><p>增值税的计税方法是：增值税应纳税额=销项税额-进项税额</p><p>这里我们要了解两个概念，销项和进项。销项指的是销售环节，进项指的是采购环节，那么销售产生的税减去采购环节的税，也就是我们所产生的利润的税，这也能够更好地理解为什么说增值税是对升值部分征收的流转税了。</p><p>此处，我们以账面无上期留抵的情况，来举个例子帮助了解：</p><p>打比方说，这个月你开了一张13%税率的票（不论普票还是专票），含税总金额是100元，那么销项税额是100➗1.13✖0.13=11.5元，而这个月你的供应商，也给你开了一张含税金额为80元的专用发票，也是13%的税率，那么进项税额就是80➗1.13✖0.13=9.2元，那么这个月你所要交的增值税就是11.5-9.2=2.3元。</p><h3 id="二、附加税" tabindex="-1">二、附加税 <a class="header-anchor" href="#二、附加税" aria-label="Permalink to &quot;二、附加税&quot;">​</a></h3><p>附加税，指的是增值税附加税，产生依据是企业当期需要缴纳增值税，计算方式是增值税的应纳税额X附加税的税率。附加税包含：城市建设维护税、教育附加税、地方教育附加 税。税率如下：</p><p>城市建设税＝增值税*7%（在市区7%；在县城、镇5%；非市区、县城和镇的1%）</p><p>教育附加费=增值税*3%</p><p>地方教育附加=增值税*2%</p><p>假如说这个月算出来我们需要交的增值税是1000元，那么对应需要交的附加税就是1000✖（7%+3%+2%）=120元。</p><p>而根据 《财政部 税务总局关于进一步支持小微企业和个体工商户发展有关税费政策的公告》（财政部 税务总局公告2023年第12号）：自2023年1月1日至2027年12月31日，对增值税小规模纳税人、小型微利企业 和个体工商户减半征收资源税（不含水资源税）、城市维护建设税、房产税、城镇土地使用税 、印花税（不含证券交易印花税）、耕地占用税 和教育费附加、地方教育附加。</p><p>也就是说，如果企业是小规模纳税人的话，那么附加税还可以减半，也就是120*0.5=60元</p><h3 id="三、企业所得税" tabindex="-1">三、企业所得税 <a class="header-anchor" href="#三、企业所得税" aria-label="Permalink to &quot;三、企业所得税&quot;">​</a></h3><p>在中华人民共和国境内，企业和其他取得收入的组织（以下统称企业）为企业所得税的纳税人。企业所得税的纳税人包括各类企业、事业单位、社会团体、民办非企业单位 和从事经营活动的其他组织。个人独资企业、合伙企业 不属于企业所得税纳税义务人。</p><p>企业所得税是以企业年利润作为依据的，计算方式为：企业所得税应纳税额=年利润✖税率。</p><p>企业所得税的税率为25%的比例税率。非居民企业 为20%。当然，企业所得税一些国家扶持下的优惠政策，主要针对小微企业。</p><h2 id="商品如何定价" tabindex="-1">商品如何定价？ <a class="header-anchor" href="#商品如何定价" aria-label="Permalink to &quot;商品如何定价？&quot;">​</a></h2><blockquote><p>比如一个面包，成本是10块，我是厂家，卖个供应商需要每个有5块的利润，那么我定价应该如何计算才能确保有5块的利润？</p><br> 再次解释下：增值税 = 销项税-进项税，所以要先求进项税，我们一般所说的成本，其实上已经是包含了进项税的！！！ <p>如果你明白了这一点，下面的公式解析 你就可以看懂了。</p></blockquote><p>在中国，商品销售通常需要缴纳增值税（VAT），具体税率根据商品类型而定。以下是详细的解答：</p><h3 id="_1-增值税及税率" tabindex="-1">1. 增值税及税率 <a class="header-anchor" href="#_1-增值税及税率" aria-label="Permalink to &quot;1. 增值税及税率&quot;">​</a></h3><ul><li><strong>增值税率</strong>：常见税率为13%（一般货物，如加工食品）、9%（如农产品、食用油）、6%（服务类）。面包作为加工食品，通常适用13%的税率。</li><li><strong>其他税种</strong>：除增值税外，还需缴纳： <ul><li><strong>城市维护建设税</strong>（增值税的7%、5%或1%）；</li><li><strong>教育费附加</strong>（增值税的3%）；</li><li><strong>地方教育附加</strong>（增值税的2%）；</li><li><strong>企业所得税</strong>（一般为25%，按利润征收）。</li></ul></li></ul><hr><h3 id="_2-定价计算-确保利润5元" tabindex="-1">2. 定价计算（确保利润5元） <a class="header-anchor" href="#_2-定价计算-确保利润5元" aria-label="Permalink to &quot;2. 定价计算（确保利润5元）&quot;">​</a></h3><p><strong>假设条件</strong>：</p><ul><li>成本10元为含税价；</li><li>增值税率13%；</li><li>附加税费合计为增值税的12%。</li></ul><p><strong>计算步骤</strong>：</p><ol><li><p><strong>不含税成本</strong>：</p><ul><li>不含税成本=10/1+13%≈8.85元</li><li>对应进项税：10 - 8.85 = 1.15元。</li></ul></li><li><p><strong>设定不含税售价为X</strong>，则：</p><ul><li><strong>销项税</strong> = X×13%</li><li><strong>应纳增值税</strong> = 销项税 - 进项税 = 0.13X - 1.15</li><li><strong>附加税费</strong> = 应纳增值税 × 12% = (0.13X - 1.15) * 0.12</li></ul></li><li><p><strong>利润方程</strong>（利润=不含税售价 - 不含税成本 - 附加税费）：<br> X - 8.85 - (0.13X - 1.15) * 0.12 = 5</p><p>解得： X ≈ 13.93 元（不含税售价） <strong>含税售价</strong> = 13.93 * 1.13 ≈ 15.74 元</p></li></ol><hr><h3 id="_3-验证计算" tabindex="-1">3. 验证计算 <a class="header-anchor" href="#_3-验证计算" aria-label="Permalink to &quot;3. 验证计算&quot;">​</a></h3><ul><li><strong>应纳增值税</strong>：<br> 13.93 * 13% - 1.15 ≈ 0.66 元</li><li><strong>附加税费</strong>：<br> 0.66 * 12% ≈ 0.079 元</li><li><strong>总成本</strong>：<br> 8.85 + 0.079 ≈ 8.93 元</li><li><strong>实际利润</strong>：<br> 13.93 - 8.93 = 5 元</li></ul><hr><h3 id="最终结论" tabindex="-1">最终结论 <a class="header-anchor" href="#最终结论" aria-label="Permalink to &quot;最终结论&quot;">​</a></h3><p>为确保每个面包利润5元，<strong>定价应为15.74元（含税）</strong>。实际操作中需注意：</p><ol><li>明确成本是否含税；</li><li>确认企业纳税人身份（一般纳税人/小规模纳税人）；</li><li>其他潜在税费（如企业所得税）对整体利润的影响。</li></ol><p><strong>公式总结</strong>：<br> 含税售价 = （不含税成本 + 目标利润 + 附加税费） × (1 + 增值税率)<br> 其中附加税费需根据增值税应纳税额计算。</p>',42),i=[e];function n(s,p,h,d,g,c){return r(),t("div",null,i)}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
